/**
 * The province and ward lists (src/data/vn-admin, regenerated by
 * scripts/fetch-vn-admin.mjs) and the lookups on them. A regenerated file
 * that breaks the shape the app relies on fails here.
 */
import { describe, it, expect } from 'vitest'
import wardsFile from '@/data/vn-admin/wards.json'
import { PROVINCES, VN_ADMIN_SOURCE, matchProvince, mergedInto, propertyProvince, provinceByCode } from './provinces'
import { wardOf, wardsOf } from './wards'
import { addressLocality, formatAddress } from './address'

const lists = wardsFile as Record<string, string[][]>
const allWards = Object.entries(lists).flatMap(([province, list]) => list.map(([code, name]) => ({ province, code, name })))
const byName = (provinceCode: string, name: string) => wardsOf(provinceCode)?.find((w) => w.name === name)

describe('the provinces', () => {
  it('are the 34 of the 2025 reorganisation, with unique two-digit codes', () => {
    expect(PROVINCES).toHaveLength(34)
    expect(new Set(PROVINCES.map((p) => p.code)).size).toBe(34)
    for (const p of PROVINCES) {
      expect(p.code).toMatch(/^\d{2}$/)
      expect(p.fullName).toBe(`${p.kind === 'city' ? 'Thành phố' : 'Tỉnh'} ${p.name}`)
      expect(p.nameEn).toBeTruthy()
    }
    expect(new Set(PROVINCES.map((p) => p.name)).size).toBe(34)
  })

  it('include the centrally-run cities', () => {
    const cities = PROVINCES.filter((p) => p.kind === 'city').map((p) => p.name)
    expect(cities).toEqual(expect.arrayContaining(['Hà Nội', 'Hồ Chí Minh', 'Hải Phòng', 'Đà Nẵng', 'Huế', 'Cần Thơ']))
  })

  it('come in Vietnamese alphabetical order (sorted once by the script, never at runtime)', () => {
    const names = PROVINCES.map((p) => p.name)
    expect(names).toEqual([...names].sort(new Intl.Collator('vi').compare))
  })

  it('say where they come from', () => {
    expect(VN_ADMIN_SOURCE.release).toBeTruthy()
    expect(VN_ADMIN_SOURCE.fetchedAt).toMatch(/^\d{4}-\d{2}-\d{2}$/)
  })
})

describe('the wards', () => {
  it('belong to one of the 34 provinces each, and every province has its own', () => {
    const codes = new Set(PROVINCES.map((p) => p.code))
    expect(new Set(Object.keys(lists))).toEqual(codes)
    for (const code of codes) expect(wardsOf(code)!.length).toBeGreaterThan(20)
  })

  it('number about 3,321 with unique five-digit codes and a type in the name', () => {
    expect(allWards.length).toBeGreaterThan(3200)
    expect(allWards.length).toBeLessThan(3400)
    expect(new Set(allWards.map((w) => w.code)).size).toBe(allWards.length)
    for (const w of allWards) {
      expect(w.code).toMatch(/^\d{5}$/)
      expect(w.name).toMatch(/^(Phường|Xã|Đặc khu) \S/)
    }
  })

  it('include the merged provinces in their new one (spot checks)', () => {
    // Hà Nội
    expect(byName('01', 'Phường Ba Đình')?.code).toBe('00004')
    expect(byName('01', 'Phường Hoàn Kiếm')).toBeDefined()
    expect(byName('01', 'Xã Ba Vì')).toBeDefined()
    // Hồ Chí Minh with the former Bình Dương and Bà Rịa - Vũng Tàu
    expect(byName('79', 'Phường Bến Thành')).toBeDefined()
    expect(byName('79', 'Phường Thủ Dầu Một')).toBeDefined()
    expect(byName('79', 'Phường Vũng Tàu')).toBeDefined()
    expect(byName('79', 'Đặc khu Côn Đảo')).toBeDefined()
    // Đà Nẵng with the former Quảng Nam
    expect(byName('48', 'Phường Hải Châu')).toBeDefined()
    expect(byName('48', 'Phường Hội An')).toBeDefined()
    expect(byName('48', 'Phường Tam Kỳ')).toBeDefined()
    expect(byName('48', 'Đặc khu Hoàng Sa')).toBeDefined()
  })

  it('are looked up within their province only', () => {
    expect(wardOf('01', '00004')).toEqual({ code: '00004', name: 'Phường Ba Đình' })
    expect(wardOf('79', '00004')).toBeUndefined()
    expect(wardOf('99', '00004')).toBeUndefined()
    expect(wardsOf('99')).toBeUndefined()
    expect(wardsOf('__proto__')).toBeUndefined()
  })
})

describe('matchProvince', () => {
  it('reads a province name however it was written', () => {
    const code = (name: string) => matchProvince(name)?.code
    for (const name of ['Hà Nội', 'Thành phố Hà Nội', 'Hanoi', 'ha noi', 'HÀ NỘI']) expect(code(name)).toBe('01')
    for (const name of ['Hồ Chí Minh', 'TP. Hồ Chí Minh', 'TP.HCM', 'TPHCM', 'Ho Chi Minh City', 'Sài Gòn']) expect(code(name)).toBe('79')
    expect(code('Thanh Hóa')).toBe('38')
    expect(code('Thanh Hoá')).toBe('38')
    expect(code('Hue')).toBe('46')
    expect(code('Thừa Thiên Huế')).toBe('46')
    expect(code('Đà Nẵng')).toBe('48')
  })

  it('does not take a merged province or a town for a current province', () => {
    for (const name of ['Bình Dương', 'Quảng Nam', 'Da Lat', 'Vũng Tàu', '', '   ']) expect(matchProvince(name)).toBeUndefined()
    expect(matchProvince(null)).toBeUndefined()
  })
})

describe('mergedInto', () => {
  it('tells where a pre-2025 province went', () => {
    expect(mergedInto('Bình Dương')?.name).toBe('Hồ Chí Minh')
    expect(mergedInto('Bà Rịa - Vũng Tàu')?.name).toBe('Hồ Chí Minh')
    expect(mergedInto('Quảng Nam')?.name).toBe('Đà Nẵng')
    expect(mergedInto('Hà Giang')?.name).toBe('Tuyên Quang')
    expect(mergedInto('Hà Nội')).toBeUndefined()
    expect(mergedInto('Da Lat')).toBeUndefined()
  })
})

describe('propertyProvince', () => {
  it('uses the saved code, else the saved city', () => {
    expect(propertyProvince({ provinceCode: '48', city: 'Hà Nội' })?.name).toBe('Đà Nẵng')
    expect(propertyProvince({ provinceCode: null, city: 'Hà Nội' })?.code).toBe('01')
    expect(propertyProvince({ provinceCode: null, city: 'Bình Dương' })).toBeUndefined()
    expect(provinceByCode('')).toBeUndefined()
  })
})

describe('formatAddress', () => {
  it('writes street, ward, province', () => {
    expect(formatAddress({ address: '12 Lý Thái Tổ', ward: 'Phường Hoàn Kiếm', district: 'Quận Hoàn Kiếm', city: 'Hà Nội' })).toBe(
      '12 Lý Thái Tổ, Phường Hoàn Kiếm, Hà Nội'
    )
  })

  it("shows an older row's district when it has no ward", () => {
    const old = { address: '5 Lê Lợi', ward: null, district: 'Thị xã Dĩ An', city: 'Bình Dương', country: 'Vietnam' }
    expect(formatAddress(old)).toBe('5 Lê Lợi, Thị xã Dĩ An, Bình Dương')
    expect(formatAddress(old, { country: true })).toBe('5 Lê Lợi, Thị xã Dĩ An, Bình Dương, Vietnam')
    expect(addressLocality(old)).toBe('Thị xã Dĩ An')
  })

  it('leaves out what is blank', () => {
    expect(formatAddress({ address: ' 1 Test ', ward: '  ', district: null, city: 'Huế' })).toBe('1 Test, Huế')
    expect(formatAddress({})).toBe('')
  })
})
